INSERT INTO levels (id, name, css_class, profile, time_hint, description, active) VALUES ('easy', 'Лёгкий', 'level-easy', 'Junior / Junior+', '15–25 мин', 'Базовая задача на 15–25 минут. Проверяет, что кандидат владеет терминологией и умеет оформить простую вещь без подсказок.', TRUE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, css_class = EXCLUDED.css_class, profile = EXCLUDED.profile, time_hint = EXCLUDED.time_hint, description = EXCLUDED.description, active = EXCLUDED.active;
INSERT INTO levels (id, name, css_class, profile, time_hint, description, active) VALUES ('medium', 'Средний', 'level-medium', 'Middle', '30–45 мин', 'Задача с неоднозначностью: данных не хватает, есть конфликт ограничений. Проверяет самостоятельность и полноту проработки.', TRUE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, css_class = EXCLUDED.css_class, profile = EXCLUDED.profile, time_hint = EXCLUDED.time_hint, description = EXCLUDED.description, active = EXCLUDED.active;
INSERT INTO levels (id, name, css_class, profile, time_hint, description, active) VALUES ('hard', 'Сложный', 'level-hard', 'Senior / Lead', '45–90 мин', 'Проектная задача на 45–90 минут: распределённые системы, компромиссы, эксплуатация. Проверяет системное мышление и опыт.', TRUE) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, css_class = EXCLUDED.css_class, profile = EXCLUDED.profile, time_hint = EXCLUDED.time_hint, description = EXCLUDED.description, active = EXCLUDED.active;
