INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('integrations', 'Интеграции', 'REST, SOAP, брокеры, файловый обмен', 'Задачи про то, как системы разговаривают друг с другом: контракты, идемпотентность, таймауты и ретраи, гарантии доставки, разбор ошибок. Самый частый блок на собеседованиях системного аналитика.', '⇄', 'SA / BA, Middle и выше', ARRAY['int-timeouts','int-idempotency','int-soap-migration','int-kafka-events','int-oauth-partner'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('system-design', 'Проектирование и системный дизайн', 'Архитектура, границы сервисов, состояния', 'Проектирование системы с нуля: границы сервисов, модель данных, состояния сущностей, синхронные и асинхронные потоки. Проверяем, умеете ли вы принимать решения и обосновывать компромиссы.', '◧', 'SA, Middle / Senior', ARRAY['des-er-catalog','des-order-state','des-notifications','des-loyalty'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('databases', 'Базы данных и SQL', 'Схемы, запросы, производительность, миграции', 'От простого SELECT до плана миграции на сотни миллионов строк: нормализация, индексы, транзакции, витрины и качество данных. Практика, которую реально дают на технических экранах.', '⛁', 'SA / BA / Data-ориентированные роли', ARRAY['db-slow-report','db-normalization','db-dwh-metrics','db-migration'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('requirements', 'Требования и коммуникации', 'Сбор, формализация, конфликты стейкхолдеров', 'Превращение «хотим как у конкурентов» в требования, по которым можно разрабатывать: user stories, критерии приёмки, альтернативные сценарии, работа с конфликтом заказчика и рисков.', '✎', 'BA / SA, Junior и выше', ARRAY['req-vague-feature','req-api-contract','req-stakeholder-conflict'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('interview-warmup', 'Разминка перед собеседованием', '6 задач на 2–3 вечера', 'Короткий набор, который покрывает типовые вопросы технического экрана: контракт API, идемпотентность, медленный запрос, модель состояний, бизнес-процесс и нефункциональные требования.', '⚡', 'Все уровни', ARRAY['req-vague-feature','int-timeouts','db-slow-report','des-order-state','int-idempotency','req-api-contract'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
INSERT INTO collections (id, title, tagline, description, icon, audience, task_ids, active) VALUES ('fintech', 'Финтех и платежи', 'Деньги, согласованность, аудит', 'Доменная подборка: платёжные потоки, согласованность данных, идемпотентность списаний, безопасность и требования регуляторов. Подходит, если собес в банк или платёжный сервис.', '₽', 'SA / BA, Middle+', ARRAY['int-idempotency','int-kafka-events','int-oauth-partner','db-migration','des-loyalty'], TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tagline = EXCLUDED.tagline, description = EXCLUDED.description, icon = EXCLUDED.icon, audience = EXCLUDED.audience, task_ids = EXCLUDED.task_ids, active = EXCLUDED.active;
